/*
 * Synthetic 2x2 character sheets as real PNG files, for the fake Codex app-server and the encoder driver (spec 096 FR-070). Plain Node: no
 * decoder, no dependency, nothing generated by a model. Kinds:
 *   transparent  four busts on a transparent background
 *   flat         the same busts on a flat colour (FR-024 keys it out)
 *   noisy        the same busts on a background too uneven to key out (FR-024: refused, a coordinator choice of 2026-10-31)
 *   bleeding     a figure that reaches over its panel's edge (FR-026)
 *   undecodable  a valid header and chunk walk, but the picture data is not a picture (FR-022)
 */
const zlib = require('zlib');

const SIDE = 1024;
const crcTable = Array.from({ length: 256 }, (_, n) => { let c = n; for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1; return c >>> 0; });
const crc = (b) => { let c = 0xffffffff; for (const v of b) c = crcTable[(c ^ v) & 255] ^ (c >>> 8); return (c ^ 0xffffffff) >>> 0; };
function chunk(type, data) {
  const len = Buffer.alloc(4); len.writeUInt32BE(data.length);
  const body = Buffer.concat([Buffer.from(type, 'latin1'), data]);
  const sum = Buffer.alloc(4); sum.writeUInt32BE(crc(body));
  return Buffer.concat([len, body, sum]);
}
function pngHeader(w, h) {
  const ihdr = Buffer.alloc(13); ihdr.writeUInt32BE(w, 0); ihdr.writeUInt32BE(h, 4); ihdr[8] = 8; ihdr[9] = 6; // 8 bits, RGBA
  return Buffer.concat([Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]), chunk('IHDR', ihdr)]);
}
/** An RGBA picture (`rgba` holds width*height*4 bytes) as a PNG file. */
function encodePng(w, h, rgba) {
  const raw = Buffer.alloc((w * 4 + 1) * h);
  for (let y = 0; y < h; y++) Buffer.from(rgba.buffer, rgba.byteOffset + y * w * 4, w * 4).copy(raw, y * (w * 4 + 1) + 1);
  return Buffer.concat([pngHeader(w, h), chunk('IDAT', zlib.deflateSync(raw, { level: 6 })), chunk('IEND', Buffer.alloc(0))]);
}

/** One bust in the panel at (px, py), panel side `s`: a head and shoulders, inside the panel's gutter unless `over`. */
function drawBust(rgba, side, px, py, s, shade, over) {
  const put = (x, y, r, g, b) => { if (x < 0 || y < 0 || x >= side || y >= side) return; const o = (y * side + x) * 4; rgba[o] = r; rgba[o + 1] = g; rgba[o + 2] = b; rgba[o + 3] = 255; };
  const cx = s / 2, hy = s * 0.34, hr = s * 0.17;
  for (let y = 0; y < s; y++) {
    for (let x = 0; x < s; x++) {
      const inHead = Math.hypot(x - cx, y - hy) < hr;
      const body = (x - cx) * (x - cx) / (s * s * 0.1) + (y - s * 0.9) * (y - s * 0.9) / (s * s * 0.1) < 1 && y < s * 0.94;
      if (!inHead && !body) continue;
      const v = (x * 7 + y * 13) % 11; // a little texture, so the encoder has something to compress
      if (inHead) put(px + x, py + y, 214 - v, 170 - v, 140 - v);
      else put(px + x, py + y, shade + v, 90 + v, 120 - v);
    }
  }
  if (over) for (let y = Math.floor(s * 0.3); y < s * 0.7; y++) for (let x = Math.floor(s * 0.5); x < s + s * 0.2; x++) put(px + x, py + y, shade, 90, 120);
}

/** The sheet as a PNG file. `side` defaults to 1024; a smaller one (at least 512) keeps a test quick. */
function sheetPng(kind = 'transparent', side = SIDE) {
  if (kind === 'undecodable') return Buffer.concat([pngHeader(side, side), chunk('IDAT', Buffer.from('this is not a compressed picture')), chunk('IEND', Buffer.alloc(0))]);
  const rgba = new Uint8Array(side * side * 4);
  if (kind === 'flat' || kind === 'noisy') {
    for (let i = 0, p = 0; i < rgba.length; i += 4, p++) {
      const n = kind === 'noisy' ? (p * 2654435761 >>> 0) % 180 : 0;
      rgba[i] = 236 - n; rgba[i + 1] = 232 - (n >> 1); rgba[i + 2] = 224; rgba[i + 3] = 255;
    }
  }
  const s = side / 2;
  const shades = [60, 70, 80, 60];
  [[0, 0], [s, 0], [0, s], [s, s]].forEach(([px, py], i) => drawBust(rgba, side, px, py, s, shades[i], kind === 'bleeding' && i === 0));
  return encodePng(side, side, rgba);
}

module.exports = { encodePng, sheetPng, SIDE };
